indexPatches.after:
solveArm: (side, target, hand) => {
  if (side === 'R') handRollR = 0; else handRollL = 0;
  solveArmIK(marine.userData['arm' + side + 'G'], marine.userData['elbow' + side + 'G'],
    hand || (side === 'R' ? _HAND_R : _HAND_L), target, side === 'R' ? _POLE_R : _POLE_L, 1);
},
setForearmRoll: (side, angle) => { if (side === 'R') handRollR = angle; else handRollL = angle; },
